-- Name: rebuild_touch_cms_taxon_concepts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rebuild_touch_cms_taxon_concepts() RETURNS void
    LANGUAGE plpgsql
    AS $$
