    ((data OPERATOR(public.->) (lower(unnest(public.higher_or_equal_ranks_names(((data OPERATOR(public.->) 'rank_name'::text))::character varying))) || '_id'::text)))::integer AS ancestor_taxon_concept_id,
    (generate_subscripts(public.higher_or_equal_ranks_names(((data OPERATOR(public.->) 'rank_name'::text))::character varying), 1) - 1) AS tree_distance
   FROM public.taxon_concepts
