    geo_entity_type character varying(255)
);


--
-- Name: api_cites_listing_changes_view; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.api_cites_listing_changes_view AS
 SELECT id,
    event_id,
    taxon_concept_id,
    original_taxon_concept_id,
        CASE
            WHEN (((change_type_name)::text = 'DELETION'::text) OR ((change_type_name)::text = 'RESERVATION_WITHDRAWAL'::text)) THEN false
            ELSE is_current
        END AS is_current,
    (effective_at)::date AS effective_at,
    species_listing_name,
    change_type_name,
        CASE
            WHEN ((change_type_name)::text = 'ADDITION'::text) THEN '+'::text
            WHEN ((change_type_name)::text = 'DELETION'::text) THEN '-'::text
            WHEN ((change_type_name)::text = 'RESERVATION'::text) THEN 'R+'::text
            WHEN ((change_type_name)::text = 'RESERVATION_WITHDRAWAL'::text) THEN 'R-'::text
            ELSE ''::text
        END AS change_type,
    inclusion_taxon_concept_id,
    listed_geo_entities_ids,
    excluded_geo_entities_ids,
    party_id,
        CASE
            WHEN (party_id IS NULL) THEN NULL::json
            ELSE row_to_json(ROW((party_iso_code)::text, (party_full_name_en)::text, (geo_entity_type)::text)::public.api_geo_entity)
        END AS party_en,
        CASE
            WHEN (party_id IS NULL) THEN NULL::json
            ELSE row_to_json(ROW((party_iso_code)::text, (party_full_name_es)::text, (geo_entity_type)::text)::public.api_geo_entity)
        END AS party_es,
        CASE
            WHEN (party_id IS NULL) THEN NULL::json
            ELSE row_to_json(ROW((party_iso_code)::text, (party_full_name_fr)::text, (geo_entity_type)::text)::public.api_geo_entity)
        END AS party_fr,
        CASE
            WHEN ((auto_note_en IS NULL) AND (inherited_full_note_en IS NULL) AND (inherited_short_note_en IS NULL) AND (full_note_en IS NULL) AND (short_note_en IS NULL) AND (nomenclature_note_en IS NULL)) THEN NULL::text
            ELSE ((
            CASE
                WHEN (length(auto_note_en) > 0) THEN (('['::text || auto_note_en) || '] '::text)
                ELSE ''::text
            END ||
            CASE
                WHEN (length(inherited_full_note_en) > 0) THEN public.strip_tags(inherited_full_note_en)
                WHEN (length(inherited_short_note_en) > 0) THEN public.strip_tags(inherited_short_note_en)
                WHEN (length(full_note_en) > 0) THEN public.strip_tags(full_note_en)
                WHEN (length(short_note_en) > 0) THEN public.strip_tags(short_note_en)
                ELSE ''::text
            END) ||
            CASE
                WHEN (length(nomenclature_note_en) > 0) THEN public.strip_tags(nomenclature_note_en)
                ELSE ''::text
            END)
        END AS annotation_en,
        CASE
            WHEN ((auto_note_es IS NULL) AND (inherited_full_note_es IS NULL) AND (inherited_short_note_es IS NULL) AND (full_note_es IS NULL) AND (short_note_es IS NULL) AND (nomenclature_note_es IS NULL)) THEN NULL::text
            ELSE ((
            CASE
                WHEN (length(auto_note_es) > 0) THEN (('['::text || auto_note_es) || '] '::text)
                ELSE ''::text
            END ||
            CASE
                WHEN (length(inherited_full_note_es) > 0) THEN public.strip_tags(inherited_full_note_es)
                WHEN (length(inherited_short_note_es) > 0) THEN public.strip_tags(inherited_short_note_es)
                WHEN (length(full_note_es) > 0) THEN public.strip_tags(full_note_es)
                WHEN (length(short_note_es) > 0) THEN public.strip_tags(short_note_es)
                ELSE ''::text
            END) ||
            CASE
                WHEN (length(nomenclature_note_en) > 0) THEN public.strip_tags(nomenclature_note_en)
                ELSE ''::text
            END)
        END AS annotation_es,
        CASE
            WHEN ((auto_note_fr IS NULL) AND (inherited_full_note_fr IS NULL) AND (inherited_short_note_fr IS NULL) AND (full_note_fr IS NULL) AND (short_note_fr IS NULL) AND (nomenclature_note_fr IS NULL)) THEN NULL::text
            ELSE ((
            CASE
                WHEN (length(auto_note_fr) > 0) THEN (('['::text || auto_note_fr) || '] '::text)
                ELSE ''::text
            END ||
            CASE
                WHEN (length(inherited_full_note_fr) > 0) THEN public.strip_tags(inherited_full_note_fr)
                WHEN (length(inherited_short_note_fr) > 0) THEN public.strip_tags(inherited_short_note_fr)
                WHEN (length(full_note_fr) > 0) THEN public.strip_tags(full_note_fr)
                WHEN (length(short_note_fr) > 0) THEN public.strip_tags(short_note_fr)
                ELSE ''::text
            END) ||
            CASE
                WHEN (length(nomenclature_note_fr) > 0) THEN public.strip_tags(nomenclature_note_fr)
                ELSE ''::text
            END)
        END AS annotation_fr,
        CASE
            WHEN ((hash_ann_symbol IS NULL) AND (hash_full_note_en IS NULL)) THEN NULL::json
            ELSE row_to_json(ROW((hash_ann_symbol)::text, public.strip_tags(hash_full_note_en))::public.api_annotation)
        END AS hash_annotation_en,
        CASE
            WHEN ((hash_ann_symbol IS NULL) AND (hash_full_note_es IS NULL)) THEN NULL::json
            ELSE row_to_json(ROW((((hash_ann_parent_symbol)::text || ' '::text) || (hash_ann_symbol)::text), public.strip_tags(hash_full_note_es))::public.api_annotation)
        END AS hash_annotation_es,
        CASE
            WHEN ((hash_ann_symbol IS NULL) AND (hash_full_note_fr IS NULL)) THEN NULL::json
            ELSE row_to_json(ROW((hash_ann_symbol)::text, public.strip_tags(hash_full_note_fr))::public.api_annotation)
        END AS hash_annotation_fr,
    show_in_history,
    full_note_en,
    short_note_en,
    auto_note_en,
    hash_full_note_en,
    hash_ann_parent_symbol,
    hash_ann_symbol,
    inherited_full_note_en,
    inherited_short_note_en,
    nomenclature_note_en,
    nomenclature_note_fr,
    nomenclature_note_es,
        CASE
            WHEN ((change_type_name)::text = 'ADDITION'::text) THEN 0
            WHEN ((change_type_name)::text = 'RESERVATION'::text) THEN 1
            WHEN ((change_type_name)::text = 'RESERVATION_WITHDRAWAL'::text) THEN 2
            WHEN ((change_type_name)::text = 'DELETION'::text) THEN 3
            ELSE NULL::integer
        END AS change_type_order
   FROM public.cites_listing_changes_mview listing_changes_mview
  WHERE show_in_history;


