  WHERE (ts.id IN ( SELECT unnest(sub.ids) AS unnest
           FROM ( SELECT array_agg(ts_1.id) AS ids
                   FROM (((((public.trade_shipments_with_taxa_view ts_1
                     JOIN public.geo_entities exporter_1 ON ((exporter_1.id = ts_1.exporter_id)))
