--
-- Name: term_trade_codes_pairs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.term_trade_codes_pairs (
    id integer NOT NULL,
    term_id integer NOT NULL,
    trade_code_id integer,
