   FROM (((public.trade_sandbox_2096
     JOIN public.trade_annual_report_uploads aru ON ((aru.id = 2096)))
     JOIN public.geo_entities ON ((geo_entities.id = aru.trading_country_id)))
     LEFT JOIN public.taxon_concepts ON ((trade_sandbox_2096.taxon_concept_id = taxon_concepts.id)));


